     1→//! Training orchestration (M7 + M8).
     2→//!
     3→//! M7: Single-image overfit trainer for validation
     4→//! M8: Multi-view training with train/test split
     5→//!
     6→//! Both optimizers currently train only the SH DC coefficient (color) for each Gaussian.
     7→//!
     8→//! Why color-only for now:
     9→//! - Validates differentiable rendering end-to-end
    10→//! - Keeps the state space small and stable for early debugging
    11→//!
    12→//! Next:
    13→//! - Add opacity + 2D eval + projection gradients for full parameter training
    14→//! - Add Gaussian densification/pruning
    15→
    16→use crate::core::{init_from_colmap_points_visible_stratified, Camera, Gaussian};
    17→use crate::io::load_colmap_scene;
    18→
    19→#[cfg(feature = "gpu")]
    20→use crate::gpu::GpuRenderer;
    21→use crate::optim::adam::{AdamF32, AdamSh16, AdamSo3, AdamVec3};
    22→use crate::optim::loss::{
    23→    l1_dssim_image_loss_and_grad_weighted, l2_image_loss_and_grad_weighted, LossKind,
    24→};
    25→use crate::core::sigmoid;
    26→use crate::render::full_diff::{
    27→    coverage_mask_bool, coverage_weights_downsampled, debug_contrib_count, debug_coverage_mask,
    28→    debug_final_transmittance, debug_overlay_means, downsample_rgb_bilinear, downsample_rgb_box,
    29→    linear_vec_to_rgb8_img, render_full_color_grads, render_full_linear, rgb8_to_linear_vec,
    30→};
    31→use image::RgbImage;
    32→use nalgebra::{Matrix3, Vector3};
    33→use rand::Rng;
    34→use rand::SeedableRng;
    35→use rand::rngs::StdRng;
    36→use rand::seq::SliceRandom;
    37→use std::collections::HashMap;
    38→use std::path::{Path, PathBuf};
    39→use std::time::Instant;
    40→use std::io::Write;
    41→
    42→/// CSV logger for training metrics
    43→struct CsvLogger {
    44→    file: std::fs::File,
    45→}
    46→
    47→impl CsvLogger {
    48→    fn new(path: &Path) -> std::io::Result<Self> {
    49→        let mut file = std::fs::File::create(path)?;
    50→        writeln!(
    51→            file,
    52→            "iteration,loss,psnr,num_gaussians,forward_ms,backward_ms,step_ms,total_ms,densify_split,densify_clone,densify_prune,grad_p50,grad_p90,bg_r,bg_g,bg_b,scale_median,aniso_median,aniso_p90,aniso_max,opacity_median,opacity_low_pct,pos_grad_median,scale_grad_median,rot_grad_median"
    53→        )?;
    54→        // Make the header visible immediately even if the process runs for a long time
    55→        // before the first row is written (e.g., when `val_interval` is large).
    56→        file.flush()?;
    57→        Ok(CsvLogger { file })
    58→    }
    59→
    60→    fn log_iteration(
    61→        &mut self,
    62→        iter: usize,
    63→        loss: f32,
    64→        psnr: f32,
    65→        num_gaussians: usize,
    66→        forward_ms: f32,
