   110→
   111→/// Statistics about Gaussian health for monitoring training
   112→#[derive(Default, Clone, Debug)]
   113→pub struct GaussianStats {
   114→    /// Median scale (geometric mean of linear x,y,z)
   115→    pub scale_median: f32,
   116→    /// Median anisotropy (max/min scale ratio)
   117→    pub aniso_median: f32,
   118→    /// 90th percentile anisotropy
   119→    pub aniso_p90: f32,
   120→    /// Maximum anisotropy
   121→    pub aniso_max: f32,
   122→    /// Median opacity (after sigmoid)
   123→    pub opacity_median: f32,
   124→    /// Percentage of Gaussians with opacity < 0.1
   125→    pub opacity_low_pct: f32,
   126→    /// Median position gradient magnitude
   127→    pub pos_grad_median: f32,
   128→    /// Median scale gradient magnitude
   129→    pub scale_grad_median: f32,
   130→    /// Median rotation gradient magnitude
   131→    pub rot_grad_median: f32,
   132→}
   133→
   134→impl GaussianStats {
   135→    /// Compute statistics from current Gaussian state
   136→    pub fn compute(
   137→        log_scales: &[Vector3<f32>],
   138→        opacity_logits: &[f32],
   139→        d_positions: Option<&[Vector3<f32>]>,
   140→        d_log_scales: Option<&[Vector3<f32>]>,
   141→        d_rot_vecs: Option<&[Vector3<f32>]>,
   142→    ) -> Self {
   143→        let n = log_scales.len();
   144→        if n == 0 {
   145→            return Self::default();
   146→        }
   147→
   148→        // Compute scale statistics
   149→        let mut scales_linear: Vec<f32> = log_scales
   150→            .iter()
   151→            .map(|s| ((s.x + s.y + s.z) / 3.0).exp()) // Geometric mean
   152→            .collect();
   153→        scales_linear.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
   154→
   155→        // Compute anisotropy for each Gaussian
   156→        let mut anisotropies: Vec<f32> = log_scales
   157→            .iter()
   158→            .map(|s| {
   159→                let max_s = s.x.max(s.y).max(s.z);
   160→                let min_s = s.x.min(s.y).min(s.z);
   161→                (max_s - min_s).exp() // Ratio in linear space
