fn scale_error(fitted: &Vector3<f32>, target: &Vector3<f32>) -> f32 {
    let fitted_linear = Vector3::new(fitted.x.exp(), fitted.y.exp(), fitted.z.exp());
    let target_linear = Vector3::new(target.x.exp(), target.y.exp(), target.z.exp());

