    // Compute relative error for each component
    let rel_errors = Vector3::new(
        (fitted_linear.x - target_linear.x).abs() / target_linear.x.max(1e-6),
        (fitted_linear.y - target_linear.y).abs() / target_linear.y.max(1e-6),
