        pos_err < 0.01,
        "Position error {} exceeds threshold 0.01",
        pos_err
    );

    assert!(
        scale_err < 0.10,
        "Scale error {:.2}% exceeds threshold 10%",
        scale_err * 100.0
    );

    assert!(
        color_err < 0.01,
        "Color error {} exceeds threshold 0.01",
        color_err
    );

    println!("✓ TC-OPT-010 passed: Single Gaussian successfully fitted to target!");
}

