        .iter()
        .zip(target.iter())
        .map(|(a, b)| (a - b).norm_squared())
        .sum::<f32>()
        / (rendered.len() as f32)
}

/// Helper: Compute L1 loss between rendered and target images
fn l1_loss(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
